import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Importe modelos e gerencie perfis","description":"","frontmatter":{"title":"Importe modelos e gerencie perfis","docId":"user.automations.templates","translationKey":"user.automations.templates","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"74217892395ddea29ed42ae4105097d815949c11029e1598a32cd2e978963f11","translationRevision":"428631380bdd7ec1bd66987025794817a1925260664c8574914f2169c9b81fa6","order":50},"headers":[],"relativePath":"pt/user/automations/templates.md","filePath":"pt/user/automations/templates.md","lastUpdated":1795735295000}`),s={name:`pt/user/automations/templates.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="import-templates-and-manage-profiles" tabindex="-1">Importe modelos e gerencie perfis <a class="header-anchor" href="#import-templates-and-manage-profiles" aria-label="Permalink to “Importe modelos e gerencie perfis”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo e pré-requisitos”">​</a></h2><p>Reutilize uma regra revisada ou uma coleção de regras sem ativar efeitos por acidente. Você precisa de <strong>Automations</strong>, de um arquivo JSON ou item de catálogo confiável e dos plugins exigidos pelas ações. Exporte o perfil atual antes de substituir uma configuração estabelecida.</p><h2 id="choose-the-right-surface" tabindex="-1">Escolha a área correta <a class="header-anchor" href="#choose-the-right-surface" aria-label="Permalink to “Escolha a área correta”">​</a></h2><p>Um documento <code>.tiktemplate.json</code> descreve um evento e suas ações. Um documento <code>.tikprofile.json</code> agrupa vários modelos. Abra o diálogo de modelos em Automations para acessar modelos integrados/personalizados, sua biblioteca do Cloud ou a importação manual de modelos. Use a barra de ferramentas de perfis para criar, selecionar, exportar e importar perfis manualmente. <strong>Plugins → Explore</strong> navega pelos plugins; modelos e perfis pertencem a esta área.</p><h2 id="review-and-import" tabindex="-1">Revise e importe <a class="header-anchor" href="#review-and-import" aria-label="Permalink to “Revise e importe”">​</a></h2><ol><li>Abra o diálogo de importação desejado e escolha um arquivo ou cole JSON compatível. Confira o nome e a origem preparados antes de continuar.</li><li>Para um modelo, inspecione o acionador, os tipos de ação e os parâmetros. Para um perfil, inspecione também a quantidade de itens e os parâmetros comuns.</li><li>Substitua destinos de exemplo, caminhos de mídia e identificadores de espectadores por valores adequados à sua configuração. Não cole credenciais em um arquivo destinado ao compartilhamento.</li><li>Aplique/importe explicitamente e aguarde o resultado. Não presuma que as definições ficam desativadas: confira os valores enabled. Selecione-as depois e revise cada ação e evento antes de ativar explicitamente os desejados.</li><li>Comece com um teste apenas de registro ou inspecione as definições primeiro. Testes de HTTP, áudio, pontos ou plugins podem executar efeitos.</li><li>Antes de confirmar perfil, revise ativação dos membros do destino e desativação dos demais, incluindo registros avulsos e membros antes desativados. Efeitos exigem gatilhos/condições; não é sync Cloud.</li></ol><p>Parâmetros como <code>{{ params.giftName }}</code> são resolvidos ao aplicar um modelo. Referências de execução como <code>{{ event.user.uniqueId }}</code> permanecem para cada evento, enquanto <a href="./variables.html">globals</a> fornece valores salvos compartilhados na execução.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado e status”">​</a></h2><p>As áreas locais de importação e exportação de modelos/perfis estão disponíveis. A navegação no Cloud exige a capacidade correspondente do host e a conta/serviço. Uma prévia de catálogo não comprova que o serviço externo de uma ação funciona. Plugins ausentes podem deixar as definições importadas inutilizáveis até serem instalados e configurados.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperação”">​</a></h2><p>Para JSON inválido, use os erros de análise informados e o tipo de documento esperado; renomear um JSON arbitrário não o converte. Para um conflito de revisão, atualize a biblioteca salva antes de aplicar novamente. Guarde o perfil exportado que funciona e consulte <a href="./../preferences/backups.html">backups</a> para os dados que a exportação de perfil não inclui.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalhes de operação”">​</a></h2><p>Importar template manual primeiro salva um documento no catálogo; aplicá-lo cria ações/eventos vinculados. O parser usa true quando <code>enabled</code> falta e a aplicação preserva esses valores. Importar perfil manual prepara entradas para revisão do proprietário. O catálogo Cloud salva templates; um perfil Cloud prepara uma mutação com procedência. Origem ou prévia bem-sucedida não garantem desativação universal. Confira comparação final e estados salvos. Na CLI use explicitamente <code>tiktools template import file.tiktemplate.json --disabled</code> ou <code>tiktools template profile-import file.tikprofile.json --disabled</code>.</p><p>Trocar perfil muda ativação: confirmar habilita membros do destino e desabilita todas as ações/eventos externos, incluindo registros avulsos. Membros antes desativados podem ser ativados. Revise ambas as listas. Efeitos ainda exigem gatilhos, condições e runtime disponíveis; a troca não envia sincronização Cloud por si só.</p><p>Experimente interativamente antes de tocar na sua configuração real:</p>`,16),t(d,{scenario:`automation`,locale:`pt`,panel:`automation`,title:`Experimente o espaço de automações`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Operações de linha de comando <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operações de linha de comando”">​</a></h2><p>Cada operação deste guia também está disponível na CLI — offline, scriptável e apta para agentes. As linhas de uso são sintaxe do parser e permanecem em inglês em todos os idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools template import &lt;file&gt; [--param k=v]... [--event-name n] [--action-name n] [--dry-run] [--no-save] [--disabled]</code></td><td>importar um modelo como regras de automação</td></tr><tr><td><code>tiktools template export --event &lt;id&gt; --out &lt;file&gt; [--title t] [--id template-id]</code></td><td>exportar uma regra de eventos como modelo</td></tr><tr><td><code>tiktools template list</code></td><td>listar os modelos da galeria</td></tr><tr><td><code>tiktools template delete &lt;template-id&gt;</code></td><td>excluir um modelo <strong>destrutivo</strong></td></tr><tr><td><code>tiktools template profile-import &lt;file&gt; [--param k=v]... [--dry-run] [--no-save] [--disabled]</code></td><td>importar um perfil de automação completo</td></tr><tr><td><code>tiktools template profile-export --out &lt;file&gt; [--name n]</code></td><td>exportar o perfil de automação</td></tr></tbody></table><p>Consulte a <a href="./../../developer/cli.html">referência completa de comandos</a> para as convenções, a saída JSON e os marcadores de operações destrutivas.</p>`,4)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};